package com.gb.astralita;
import com.gb.astralita.registry.*; import com.gb.astralita.world.ModWorldgen; import net.minecraft.world.item.CreativeModeTabs; import net.minecraftforge.event.BuildCreativeModeTabContentsEvent; import net.minecraftforge.eventbus.api.IEventBus; import net.minecraftforge.fml.common.Mod; import net.minecraftforge.fml.javafmlmod.FMLJavaModLoadingContext;
@Mod(AstralitaMod.MODID) public class AstralitaMod { public static final String MODID="astralita"; public AstralitaMod(){IEventBus b=FMLJavaModLoadingContext.get().getModEventBus();ModBlocks.register(b);ModItems.register(b);ModWorldgen.register(b);b.addListener(this::tabs);} private void tabs(BuildCreativeModeTabContentsEvent e){if(e.getTabKey()==CreativeModeTabs.INGREDIENTS){e.accept(ModItems.FRAGMENTO_ASTRAL);e.accept(ModItems.BARRA_ASTRALITA);}if(e.getTabKey()==CreativeModeTabs.NATURAL_BLOCKS){e.accept(ModBlocks.MINERIO_ASTRALITA);e.accept(ModBlocks.BLOCO_ASTRALITA);}if(e.getTabKey()==CreativeModeTabs.COMBAT){e.accept(ModItems.ESPADA_ASTRALITA);e.accept(ModItems.CAPACETE_ASTRALITA);e.accept(ModItems.PEITORAL_ASTRALITA);e.accept(ModItems.CALCAS_ASTRALITA);e.accept(ModItems.BOTAS_ASTRALITA);}if(e.getTabKey()==CreativeModeTabs.TOOLS_AND_UTILITIES){e.accept(ModItems.PICARETA_ASTRALITA);e.accept(ModItems.MACHADO_ASTRALITA);e.accept(ModItems.PA_ASTRALITA);e.accept(ModItems.ENXADA_ASTRALITA);}}}
